             OR remind_msg LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY
    CASE WHEN status = 'triggered' AND is_read = 0 THEN 0 ELSE 1 END ASC,
    CASE WHEN status = 'triggered' AND is_read = 0 THEN trigger_time ELSE IFNULL(next_remind_time, remind_time) END DESC
LIMIT #{offset}, #{limit}

